import numpy as np

def kmeans(x, k, iters=20, seed=0):
    rng = np.random.default_rng(seed)
    c = x[rng.choice(len(x), k, replace=False)].copy()
    for _ in range(iters):
        d = (x**2).sum(1)[:, None] - 2 * x @ c.T + (c**2).sum(1)[None]
        a = d.argmin(1)
        for i in range(k):
            pts = x[a == i]
            if len(pts): c[i] = pts.mean(0)
    return c

def train(xt, m, ks=256):
    D = xt.shape[1]; ds = D // m
    return np.stack([kmeans(xt[:, j*ds:(j+1)*ds], ks) for j in range(m)])

def encode(cb, x):
    m, ks, ds = cb.shape
    codes = np.empty((len(x), m), dtype=np.uint8)
    for j in range(m):
        s = x[:, j*ds:(j+1)*ds]
        d = ((s[:, None, :] - cb[j][None]) ** 2).sum(-1)
        codes[:, j] = d.argmin(1)
    return codes

def adc_search(cb, codes, q, k=10):
    m, ks, ds = cb.shape
    lut = ((q.reshape(m, 1, ds) - cb) ** 2).sum(-1)    # m x ks table
    est = lut[np.arange(m), codes].sum(1)             # gather + sum
    top = np.argpartition(est, k)[:k]
    return top[np.argsort(est[top])]
